define('text!PoE/Widget/League/Ladder/Ladder.hbt',[],function () { return '{{#if options.title}}\n    <h2>{{options.title}}</h2>\n{{else}}\n    {{#unless options.hideTitle}}\n        <h2>{{translate "Ladder"}}</h2>\n    {{/unless}}\n{{/if}}\n\n<div class="controls">\n    {{#unless options.unfilterable}}\n    <label for="classFilter">{{translate "Class Filter"}}:</label>\n    <select name="classFilter">\n        <option value="null" selected>{{translate "All"}}</option>\n        <option value="0">{{translate "Scion"}}</option>\n        <option value="1">{{translate "Marauder"}}</option>\n        <option value="2">{{translate "Ranger"}}</option>\n        <option value="3">{{translate "Witch"}}</option>\n        <option value="4">{{translate "Duelist"}}</option>\n        <option value="5">{{translate "Templar"}}</option>\n        <option value="6">{{translate "Shadow"}}</option>\n    </select>\n    {{/unless}}\n    {{#if options.hideDelve}}\n    <label for="hideDelve">{{translate "Hide Delve Depth"}}:</label>\n    <input type="checkbox" value="1" name="hideDelve" id="hideDelve" checked="checked">\n    {{/if}}\n    <label for="autoRefresh">{{translate "Auto refresh"}}:</label>\n    <input type="checkbox" value="1" name="autoRefresh" id="autoRefresh">\n    <input type="button" class="refresh button1" value="{{translate "Refresh"}}" />\n    {{#if league}}\n        <a class="exportCsv button1" href="/ladder/export-csv/league/{{uc league.id}}?realm={{league.realm}}">{{translate "Export CSV"}}</a>\n    {{/if}}\n</div>\n<div class="loading"></div>\n<table>\n    <thead>\n            <tr>\n                <th>{{translate "Rank"}}</th>\n                <th>{{translate "Account"}}</th>\n                <th>{{translate "Character"}}</th>\n                <th>{{translate "Class"}}</th>\n                <th>{{translate "Level"}}</th>\n                {{#if league.timedEvent}}\n                <th>{{translate "Experience"}}</th>\n                {{else}}\n                <th class="sortable" data-sort>{{translate "Experience"}}</th>\n                {{/if}}\n                {{#if league.delveEvent}}\n                <th class="sortable{{#ifCond options.sort \'==\' \'depth\'}} sorted{{/ifCond}}" data-sort="depth">{{translate "Depth"}}</th>\n                <th class="sortable{{#ifCond options.sort \'==\' \'depthsolo\'}} sorted{{/ifCond}}" data-sort="depthsolo">{{translate "Depth (Solo)"}}</th>\n                {{/if}}\n                {{#if league.ancestorEvent}}\n                <th class="sortable{{#ifCond options.sort \'==\' \'ancestor\'}} sorted{{/ifCond}}" data-sort="ancestor">{{translate "Ancestor Rank"}}</th>\n                {{/if}}\n                {{#if league.timedEvent}}\n                <th class="sortable" data-sort>{{translate "Time"}}</th>\n                {{/if}}\n                {{#if league.scoreEvent}}\n                <th class="sortable{{#ifCond options.sort \'==\' \'score\'}} sorted{{/ifCond}}" data-sort="score">{{translate "Score"}}</th>\n                {{/if}}\n            </tr>\n    </thead> \n    <tbody class="entries"></tbody>\n</table>\n<div class="pagination"></div>\n';});


define('text!PoE/Widget/League/Ladder/PVPLadder.hbt',[],function () { return '{{#if options.title}}\r\n<h2>{{options.title}}</h2>\r\n{{else}}\r\n{{#unless options.hideTitle}}\r\n<h2>{{translate "Ladder"}}</h2>\r\n{{/unless}}\r\n{{/if}}\r\n\r\n<div class="controls">\r\n    <label for="autoRefresh">{{translate "Auto refresh"}}</label>\r\n    <input type="checkbox" value="1" name="autoRefresh" id="autoRefresh">\r\n    <input type="button" class="refresh button1" value="{{translate "Refresh"}}" />\r\n    {{#if league}}\r\n    <a class="exportCsv button1" href="/ladder/export-csv/league/{{uc league.id}}?realm={{league.realm}}">{{translate "Export CSV"}}</a>\r\n    {{/if}}\r\n</div>\r\n<div class="loading"></div>\r\n<table>\r\n    <thead>\r\n    <tr>\r\n        <th>{{translate "Rank"}}</th>\r\n        <th>{{translate "Members"}}</th>\r\n\r\n        {{#if league.glickoRatings}}\r\n        <th>{{translate "Rating"}}</th>\r\n        {{else}}\r\n\r\n        {{#ifCond league.style "===" "Swiss"}}\r\n        <th>{{translate "Games Played"}}</th>\r\n        <th>{{translate "Points"}}</th>\r\n        {{else}}\r\n        <th>{{translate "Points"}}</th>\r\n        <th>{{translate "Games Played"}}</th>\r\n        {{/ifCond}}\r\n        <th class="tiebreaker-hover">{{translate "Resistance"}}</th>\r\n        {{/if}}\r\n    </tr>\r\n    </thead>\r\n    <tbody class="entries"></tbody>\r\n</table>\r\n<div class="pagination"></div>\r\n';});


define('text!PoE/Widget/League/Ladder/PathOfEnduranceLadder.hbt',[],function () { return '<div class="labyrinth-ladder-controls">\r\n    <div class="poeForm">\r\n        <button id="ladder-prev" class="button1" style="display: {{#if league.prev}}inline-block{{else}}none{{/if}};">{{translate "Prev"}}</button>\r\n        <select class="league">\r\n            {{#each league.leagueOps}}\r\n            <option value="{{this}}" {{#ifCond this "==" ../league.leagueName}} selected {{/ifCond}}>{{this}}</option>\r\n            {{/each}}\r\n        </select>\r\n        <button id="ladder-next" class="button1" style="display: {{#if league.next}}inline-block{{else}}none{{/if}};">{{translate "Next"}}</button>\r\n\r\n    </div>\r\n</div>\r\n\r\n{{#if options.title}}\r\n<h2 id="ladder-title">{{options.title}}</h2>\r\n{{else}}\r\n{{#unless options.hideTitle}}\r\n<h2>{{translate "Ladder"}}</h2>\r\n{{/unless}}\r\n{{/if}}\r\n\r\n<div class="controls">\r\n    <label for="autoRefresh">{{translate "Auto refresh"}}</label>\r\n    <input type="checkbox" value="1" name="autoRefresh" id="autoRefresh">\r\n    <input type="button" class="refresh button1" value="{{translate \'Refresh\'}}" />\r\n</div>\r\n<div class="clear"></div>\r\n{{#if league.date}}\r\n<h2 id="ladder-time">{{translate "Start"}}: {{unixMoment league.startTime format=\'lll\'}}</h2>\r\n{{/if}}\r\n<div class="loading"></div>\r\n<table>\r\n    <thead>\r\n    <tr>\r\n        <th>{{translate "Rank"}}</th>\r\n        <th>{{translate "Account"}}</th>\r\n        <th>{{translate "Class"}}</th>\r\n        <th>{{translate "Score"}}</th>\r\n    </tr>\r\n    </thead>\r\n    <tbody class="entries"></tbody>\r\n</table>\r\n<div class="pagination"></div>';});


define('text!PoE/Widget/League/Ladder/EventLadder.hbt',[],function () { return '{{#if options.title}}\n<h2>{{options.title}}</h2>\n{{else}}\n{{#unless options.hideTitle}}\n<h2>{{translate "Ladder"}}</h2>\n{{/unless}}\n{{/if}}\n\n<div class="controls">\n<label for="autoRefresh">{{translate "Auto refresh"}}:</label>\n<input type="checkbox" value="1" name="autoRefresh" id="autoRefresh">\n<input type="button" class="refresh button1" value="{{translate "Refresh"}}" />\n{{#if false}}\n<a class="exportCsv button1" href="/ladder/export-csv/league/{{uc league.id}}?realm={{league.realm}}">{{translate "Export CSV"}}</a>\n{{/if}}\n</div>\n<div class="loading"></div>\n<table>\n<thead>\n<tr>\n  <th>{{translate "Rank"}}</th>\n  <th>{{translate "League"}}</th>\n  <th></th>\n  {{#if league.timedEvent}}\n  <th>{{translate "Time"}}</th>\n  {{/if}}\n  {{#if league.scoreEvent}}\n  <th>{{translate "Score"}}</th>\n  {{/if}}\n</tr>\n</thead>\n<tbody class="entries"></tbody>\n</table>\n<div class="pagination"></div>\n';});

