define('text!PoE/Widget/Guild/MemberPanel.hbt',[],function () { return '<div class="frame">\r\n    <div class="background"></div>\r\n    <div class="top"></div>\r\n    <div class="bottom"></div>\r\n    <div class="content">\r\n        <div class="guild"></div>\r\n    </div>\r\n</div>\r\n<div class="memberPanel">\r\n    <div class="frame">\r\n        <div class="background"></div>\r\n        <div class="top"></div>\r\n        <div class="bottom"></div>\r\n        <div class="content">\r\n            <div class="createTransaction">\r\n                <h2>{{translate "Give Microtransaction Points to Guild"}}</h2>\r\n                <p>{{translate "Use this form to send points to your Guild to allow your Guild Leader to purchase Microtransactions. If the Guild Leader accepts your points you can not be kicked out for three months."}}</p>\r\n                <div class="formT1">\r\n                    <div class="row points">\r\n                        <label for="points">{{translate "Points Amount"}}:</label>\r\n                        <div class="element">\r\n                            <input type="text" name="points" class="points">\r\n                            <ul></ul>\r\n                            <div class="success message"></div>\r\n                        </div>\r\n                    </div>\r\n                    <div class="row"><div class="element">\r\n                      {{#if showCoins}}\r\n                        <button style="width: 100%" data-platform="pc" class="createTransaction regularPointsIcon button1 important">{{translate "Donate Points"}}</button>\r\n                      {{/if}}\r\n                      {{#if showSonyCoins}}\r\n                        <button style="width: 100%" data-platform="sony" class="createTransaction psnPointsIcon button1 important">{{translate "Donate Points"}}</button>\r\n                      {{/if}}\r\n                    </div></div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class="frame">\r\n        <div class="background"></div>\r\n        <div class="top"></div>\r\n        <div class="bottom"></div>\r\n        <div class="content">\r\n            <div class="currentTransactions">\r\n                <h2>{{translate "Transaction History"}}</h2>\r\n                <div class="entries"></div>\r\n                <div class="pagination"></div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<script setup lang="ts">\r\n</script>';});

