define('text!PoE/View/PrivateLeague/Member.hbt',[],function () { return '<div class="">\r\n    {{memberName}}\r\n</div>\r\n<div class="right half">\r\n    {{#if isReAddable }}\r\n    <div class="row"><label for="re_add_{{id}}">{{ translate \'Re-add\' }}</label>\r\n        <div class="element">\r\n            <input type="checkbox" id="re_add_{{id}}" name="re-add" value="{{id}}"> </div>\r\n    </div>\r\n    {{/if}}\r\n    {{#if isAcceptable}}\r\n    <div class="row"><label for="accept_request_{{id}}">{{ translate \'Accept\' }}</label>\r\n        <div class="element">\r\n            <input type="checkbox" id="accept_request_{{id}}" name="accept" value="{{id}}"> </div>\r\n    </div>\r\n\r\n    {{/if}}\r\n    {{#if promote}}\r\n    <div class="row"><label for="promote_{{id}}">{{ translate \'Promote\' }}</label>\r\n        <div class="element">\r\n            <input type="checkbox" id="promote_{{id}}" name="promote" value="{{id}}">\r\n        </div>\r\n    </div>\r\n    {{/if}}\r\n    {{#if makeOwner}}\r\n    <div class="row"><label for="owner_{{id}}">{{ translate \'Make Owner\' }}</label>\r\n        <div class="element">\r\n            <input type="checkbox" id="owner_{{id}}" class="make-owner" name="owner" value="{{id}}">\r\n        </div>\r\n    </div>\r\n    {{/if}}\r\n</div>\r\n<div class="right">\r\n    <div class="{{privateLeagueRoleClassName role}} role">\r\n        {{roleName}}\r\n    </div>\r\n    <div class="remove">\r\n        {{#if isAcceptable}}\r\n        <div class="element">\r\n            <input type="checkbox" id="deny_request_{{id}}" name="deny" value="{{id}}">\r\n        </div>\r\n        {{/if}}\r\n        {{#if isRemovable}}\r\n        <div class="element">\r\n            <input type="checkbox" id="remove_{{id}}" name="remove" value="{{id}}">\r\n        </div>\r\n        {{/if}}\r\n    </div>\r\n</div>';});

