define('text!PoE/View/PrivateLeague/ManageMember.hbt',[],function () { return '{{#ifCond editable "===" true}}\r\n{{#if invitation}}\r\n<div>\r\n    <fieldset class="generate-link-container">\r\n        <div class="row">\r\n            <h4 class="section-header">{{ translate \'Generate Invitation Link\' }}</h4>\r\n            {{#ifCond invitation.validKeys.length "<" 10}}\r\n            <div class="row generate-link-form">\r\n                <input type="radio" name="set-expiration-time" id="24-hours" value="true" checked="checked"><label for="24-hours">{{ translate \'Expire in 24 hours\' }}</label>\r\n                <input type="radio" name="set-expiration-time" id="no-expiration-time" value="false"><label for="no-expiration-time">{{ translate \'No Expiration Time\' }}</label>\r\n                <button class="generate-link red">{{ translate \'Generate Link\' }}</button>\r\n            </div>\r\n            <div class="error generate-link-error hidden">\r\n               {{ translate \'Sorry, an error occurred.\' }}\r\n            </div>\r\n            {{/ifCond}}\r\n            <div class="element">\r\n            {{#if invitation.validKeys}}\r\n            {{#each invitation.validKeys}}\r\n                <div class="invitation-link-container">\r\n                    <input class="invitation-link" readonly="readonly" type="text" id="invitation-link-{{@index}}"\r\n                        aria-label="Link to share" value="{{link}}">\r\n                    <button class="copy-text red" data-index="{{@index}}">{{ translate \'Copy\' }}</button>\r\n                    <p>\r\n                        {{ translate \'Generated By:\' }} <span class="invitation-generated-account">{{account}}</span>\r\n                    </p>\r\n                    <p class="invitation-expiration">\r\n                        {{ translate \'Expiration Time:\' }}\r\n                         <span class="invitation-expiration-time">\r\n                        {{#if endTime}}\r\n                            {{moment endTime.date}}\r\n                        {{else}}\r\n                            {{ translate \'Forever\' }}\r\n                        {{/if}}\r\n                    </span>\r\n                    </p>\r\n                </div>\r\n            {{/each}}\r\n            {{/if}}\r\n            </div>\r\n        </div>\r\n        <div class="row">\r\n            {{#ifCond invitation.expiredKeys.length ">" 0}}\r\n                <a class="show-expired" href="">{{ translate \'Show Expired Links\' }}</a>\r\n            {{/ifCond}}\r\n        </div>\r\n    </fieldset>\r\n    {{#ifCond invitation.expiredKeys.length ">" 0}}\r\n    <fieldset class="generate-link-container expired-links-container hidden">\r\n        <h3>{{ translate \'Expired Links\' }}</h3>\r\n        <div class="row">\r\n            {{#each invitation.expiredKeys}}\r\n                <p class="invitation-expiration">{{link}}</p>\r\n                <p>{{ translate \'Generated By:\' }} {{account}}</p>\r\n                <p>{{ translate \'Expiration Time:\' }} {{#if endTime}}{{moment endTime.date}}{{/if}}</p>\r\n                <br/>\r\n            {{/each}}\r\n        </div>\r\n    </fieldset>\r\n    {{/ifCond}}\r\n    <div class="row">\r\n      <div class="element">\r\n        <input type="submit" class="update-member" value="{{ translate \'Update Members\' }}"> </div>\r\n    </div>\r\n</div>\r\n{{/if}}\r\n{{/ifCond}}';});


define('text!PoE/View/PrivateLeague/Roles.hbt',[],function () { return '<label>{{ translate \'Role\' }}</label>\r\n<select class="filter-role">\r\n    <option value="">{{ translate \'Show All Players\' }}</option>\r\n    {{#each .}} \r\n    <option value="{{key}}">{{value}}</option>\r\n    {{/each}}\r\n</select>\r\n\r\n';});

