define('text!PoE/Ascendancy/Ascendancy.hbt',[],function () { return '<svg version="1.1" viewBox="0 0 {{frameW}} {{frameH}}" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">\r\n    <!-- defining image icons and lines -->\r\n    <defs>\r\n        <filter id="Darken">\r\n            <feColorMatrix in="SourceGraphic" type="saturate" values="0.3" />\r\n        </filter>\r\n        {{#each sprites}}\r\n        <image id="{{@key}}" {{#with (lookup this "0.8")~}} xlink:href="{{filename}}" width="{{w}}" height="{{h}}" {{/with}} preserveAspectRatio="none" />\r\n        {{/each}}\r\n        {{#each sprites}}\r\n        {{#each this}}\r\n        {{#each coords}}\r\n        <symbol id="{{@key}}" viewBox="0 0 {{w}} {{h}}">\r\n          <use xlink:href="#{{@../../key}}" transform="translate(-{{x}}, -{{y}})" />\r\n        </symbol>\r\n        {{/each}}\r\n        {{/each}}\r\n        {{/each}}\r\n        <clipPath id="background-clip" clipPathUnits="userSpaceOnUse">\r\n          <circle cx="{{math frameW \'/\' 2}}" cy="{{math frameH \'/\' 2}}" r="{{math frameW \'/\' 2}}" />\r\n        </clipPath>\r\n    </defs>\r\n    <g>\r\n      <!-- frame -->\r\n      <use xlink:href="#{{fixIconPaths ascData.background}}" x="0" y="0" width="{{frameW}}" height="{{frameH}}" clip-path="url(#background-clip)"></use>\r\n      <use xlink:href="#{{fixIconPaths titlePlaque.image}}" x="{{titlePlaque.x}}" y="{{titlePlaque.y}}" width="{{titlePlaque.width}}" height="{{titlePlaque.height}}"></use>\r\n      <text text-anchor="middle" fill="#7CB29C" x="{{titlePlaque.centerX}}" y="{{math titlePlaque.height \'/\' 1.6}}" class="FontinRegular" style="font-size: 20px; color: #ffeac5; user-select: none;">{{ascData.displayName}}</text>\r\n      <!-- flavour text -->\r\n      {{drawAscendancyFlavourText flavourText}}\r\n      <!-- draw lines -->\r\n      {{drawAscendancyLines nodes}}\r\n      <!-- draw icons -->\r\n      {{#each nodes}}\r\n        <g class="node-group">\r\n          {{drawAscendancyNode this @key}}\r\n      </g>\r\n      {{/each}}\r\n    </g>\r\n</svg>\r\n';});

