define('text!PoE/View/DivinationCard/Preview.hbt',[],function () { return '<h5 class="card-draft">Preview</h5>\r\n<div class="FontinSmallCaps card-preview">\r\n    <div class="card-face">\r\n        <img class="card-face-image" alt="" src="{{cardFace}}" width="237" height="170">\r\n    </div>\r\n    <div class="card-frame">\r\n        <div class="card-content card-name">{{#if name }}{{name}}{{else}}{{translate "Name"}}{{/if}}</div>\r\n        <div class="card-content card-reward">\r\n            <div class="card-content card-stack-size">*</div>\r\n            {{translate "Reward"}}\r\n        </div>\r\n        <div class="card-content card-divider"></div>\r\n        <div class="card-content card-flavour-text"><div>{{#if flavourText }}{{flavourText}}{{else}}{{translate "Flavour Text"}}{{/if}}</div></div>\r\n    </div>\r\n    {{#unless manageCard}}\r\n    <p class="card-warning">Please do not reveal your Divination Card prior to its release. Contact us for more information.</p>\r\n    {{/unless}}\r\n</div>';});

